package com.opsnexus.governance;
import com.opsnexus.common.ApiResponse;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/dashboard") public class DashboardController{
 private final JdbcTemplate db;public DashboardController(JdbcTemplate db){this.db=db;}
 @GetMapping public ApiResponse<?> dashboard(@AuthenticationPrincipal Jwt jwt){long user=Long.parseLong(jwt.getSubject());boolean admin="ADMIN".equals(jwt.getClaimAsString("role"));var stats=new LinkedHashMap<String,Object>();stats.put("knowledgeBases",count("SELECT COUNT(*) FROM knowledge_base WHERE status='ACTIVE'"));stats.put("publishedDocuments",count("SELECT COUNT(*) FROM document_version WHERE publish_status='PUBLISHED' AND process_status='READY'"));stats.put("conversations",admin?count("SELECT COUNT(*) FROM conversation"):count("SELECT COUNT(*) FROM conversation WHERE user_id=?",user));stats.put("diagnoses",admin?count("SELECT COUNT(*) FROM diagnosis_record"):count("SELECT COUNT(*) FROM diagnosis_record WHERE user_id=?",user));if(admin)stats.put("openGaps",count("SELECT COUNT(*) FROM knowledge_gap WHERE status='OPEN'"));var recentDiagnoses=admin?db.queryForList("SELECT id,service_name,symptom,status,created_at FROM diagnosis_record ORDER BY created_at DESC LIMIT 5"):db.queryForList("SELECT id,service_name,symptom,status,created_at FROM diagnosis_record WHERE user_id=? ORDER BY created_at DESC LIMIT 5",user);var recentDocuments=db.queryForList("SELECT d.title,v.version_no,v.published_at FROM document_version v JOIN knowledge_document d ON d.id=v.document_id WHERE v.publish_status='PUBLISHED' ORDER BY v.published_at DESC LIMIT 5");return ApiResponse.ok(Map.of("stats",stats,"recentDiagnoses",recentDiagnoses,"recentDocuments",recentDocuments));}
 private long count(String sql,Object...args){return db.queryForObject(sql,Long.class,args);}
}
